    block:header:5
        H0["dp[i][j]"] H1["∅"] H2["r"] H3["o"] H4["s"]
    end
    block:row0:5
        R00["∅"] R01["0"] R02["1"] R03["2"] R04["3"]
    end
    block:row1:5
        R10["h"] R11["1"] R12["1"] R13["2"] R14["3"]
    end
    block:row2:5
        R20["o"] R21["2"] R22["2"] R23["1"] R24["2"]
    end
    block:row3:5
        R30["r"] R31["3"] R32["2"] R33["2"] R34["2"]
    end
    block:row4:5
        R40["s"] R41["4"] R42["3"] R43["3"] R44["2"]
    end
    block:row5:5
        R50["e"] R51["5"] R52["4"] R53["4"] R54["3"]
    end
```

> 右下角的 **3** 即为 `"horse"` → `"ros"` 的最小编辑距离。

### TypeScript 实现

```typescript
function minDistance(s: string, t: string): number {
  const m = s.length;
  const n = t.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (s[i - 1] === t[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
      }
    }
  }

  return dp[m][n];
}
```

空间优化版本（两行滚动）：

```typescript
function minDistanceOptimized(s: string, t: string): number {
  const m = s.length;
  const n = t.length;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  let curr = new Array(n + 1).fill(0);

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      if (s[i - 1] === t[j - 1]) {
        curr[j] = prev[j - 1];
      } else {
        curr[j] = 1 + Math.min(prev[j], curr[j - 1], prev[j - 1]);
      }
    }
    [prev, curr] = [curr, prev];
  }

  return prev[n];
}
```

### 复杂度分析

| 指标       |    二维版本     |  空间优化版本   |
| :--------- | :-------------: | :-------------: |
| 时间复杂度 | $O(m \times n)$ | $O(m \times n)$ |
| 空间复杂度 | $O(m \times n)$ |     $O(n)$      |

